const card = document.querySelector('#services .categories ul');
const title = card?.querySelector('h2,h3');
const icon = card?.querySelector('li > i');
const heading = title?.getBoundingClientRect();
const glyph = icon?.getBoundingClientRect();
if (!heading || !glyph || glyph.width <= 0 || heading.left <= glyph.right || Math.max(heading.top, glyph.top) >= Math.min(heading.bottom, glyph.bottom)) throw new Error('Service title and category icon no longer share one line with their original gap');
const underline = getComputedStyle(title, '::after');
if (underline.content !== '""' || parseFloat(underline.height) <= 0 || !underline.backgroundImage.includes('linear-gradient')) throw new Error('Native service title underline is missing');
const homeServiceCards = [...document.querySelectorAll('.categories ul')];
if (homeServiceCards.length !== 6) throw new Error('Expected six native service cards');
for (const card of homeServiceCards) {
  if (getComputedStyle(card).boxShadow !== 'rgba(224, 235, 235, 0.5) 1px 0px 17px 3px') throw new Error('Service card lost its original fixed shadow');
  for (const item of card.querySelectorAll('li:first-of-type ~ li')) {
    if (getComputedStyle(item).textShadow !== 'rgb(19, 22, 22) 1px 1px 2px') throw new Error('Service text lost its original fixed shadow');
  }
  const title = card.querySelector('.service-title, h3');
  if (!title) throw new Error('Missing native service title');
  const underline = getComputedStyle(title, '::after');
  if (underline.bottom !== '-1px' || underline.left !== '-2px') throw new Error('Service title underline shifted from its original offsets');
}

