const surface = document.querySelector('.cv-detail-surface');
if (!surface || surface.classList.contains('cv-container-surface') || surface.querySelector('.cv-zoom-back')) throw new Error('Regular CV details gained a zoom-back control or lost their surface');
const bounds = surface.getBoundingClientRect();
const near = (actual, expected, label) => {
  if (Math.abs(actual - expected) > 0.02) throw new Error('CV corner spacing differs: ' + label + ' ' + actual + ' !== ' + expected);
};
for (const selector of ['.cv-from', '.cv-to']) {
  const year = surface.querySelector(':scope > ' + selector);
  if (!year) throw new Error('Missing CV year: ' + selector);
  const style = getComputedStyle(year);
  const fontSize = Number.parseFloat(style.fontSize);
  const rect = year.getBoundingClientRect();
  near(Number.parseFloat(style.marginTop), 0.3 * fontSize, selector + ' top margin');
  near(Number.parseFloat(style.marginLeft), 0.6 * fontSize, selector + ' side margin');
  near(rect.top - bounds.top, 0.3 * fontSize, selector + ' upper corner');
  near(selector === '.cv-from' ? rect.left - bounds.left : bounds.right - rect.right, 0.6 * fontSize, selector + ' outer corner');
}

