const gutterNarrow = innerWidth === 400;
if (!gutterNarrow && innerWidth !== 1440) throw new Error('Unsupported native gutter viewport');
const gutterNear = (actual, expected, label) => { if (Math.abs(actual - expected) > 0.02) throw new Error('Native gutter differs: ' + label + ' ' + actual + ' !== ' + expected); };
const gutterFill = document.querySelector('.fill-side-top > div');
if (!gutterFill) throw new Error('Native upper-right gutter is missing');
const gutterExpanded = gutterFill.classList.contains('adjust-for-fullscreen');
const gutterWidth = gutterNarrow ? (gutterExpanded ? 6.3125 : 2.3125) : (gutterExpanded ? 218 : 214);
gutterNear(gutterFill.getBoundingClientRect().width, gutterWidth, 'upper-right width');
gutterNear(gutterFill.getBoundingClientRect().left, innerWidth - gutterWidth, 'upper-right position');
gutterNear(parseFloat(getComputedStyle(gutterFill).borderLeftWidth), gutterExpanded ? 2 : 0, 'upper-right border');
const gutterBefore = document.querySelector('.header-before');
if (gutterExpanded) {
  if (!gutterBefore || !document.querySelector('#footer-sticky.adjust-for-fullscreen')) throw new Error('Expanded shell lost its native framing owners');
  gutterNear(gutterBefore.getBoundingClientRect().width, gutterNarrow ? 4.3125 : 216, 'upper-left width');
} else if (gutterBefore) throw new Error('Normal shell gained an expanded framing owner');
const gutterFooters = [...document.querySelectorAll('footer')];
if (gutterFooters.length !== 2) throw new Error('Native shell must retain both footer copies');
for (const footer of gutterFooters) {
  const before = getComputedStyle(footer, '::before');
  gutterNear(parseFloat(before.width), gutterNarrow ? 2.32 : 214, 'footer leading width');
  gutterNear(parseFloat(before.left), gutterNarrow ? -4.32 : -216, 'footer leading offset');
  if (footer.classList.contains('adjust-for-fullscreen')) {
    const after = getComputedStyle(footer, '::after');
    gutterNear(parseFloat(after.width), gutterNarrow ? 4.32 : 216, 'footer trailing width');
    gutterNear(parseFloat(after.right), gutterNarrow ? -4.32 : -216, 'footer trailing offset');
  }
}

