// Compare native geometric progress, not an assumed duration or class name.
function verifyProgress(samples, expected, viewport) {
  const first = samples[0], final = samples.at(-1);
  if (!first || final.rows.length !== 2 || first.outer <= 0 || final.outer <= first.outer)
    throw new Error('Reply growth requires the original placeholder and two actual sibling rows');
  if (samples.some((value, index) => value.scrollX !== first.scrollX || value.scrollY !== first.scrollY ||
      value.viewport[0] !== viewport[0] || value.viewport[1] !== viewport[1] ||
      value.outer < first.outer || (index > 0 && value.outer < samples[index - 1].outer)))
    throw new Error('Reply growth lost its footprint or moved the settled viewport');
